55	export async function setSpecStatus(path: string, status: SpecStatus): Promise<void> {
56	  const text = await readFile(path, 'utf8')
57	  await writeFile(path, withStatus(text, status), 'utf8')
58	}
59	
60	export function withStatus(text: string, status: SpecStatus): string {
61	  return withFrontMatterValue(text, 'status', status)
62	}
