10	/**
11	 * A feature's working files are kept this long after they were last touched,
12	 * once the feature is finished or its spec is gone: long enough for the Tasks
13	 * tab to stay readable after verification, and to outlast a branch switch that
14	 * hides the spec for a while.
15	 */
16	export const WORKING_FILES_KEPT_MS = 7 * 24 * 60 * 60 * 1000
