20	/** Workspace-relative paths, by what happened to them. */
21	export type SweepReport = {
22	  /** Markdown task boards converted to JSON. */
23	  converted: string[]
24	  /** Working files moved out of `plan/`, where they lived before they had a directory of their own. */
25	  moved: string[]
26	  /** Working files left in `plan/` because the working directory already holds one of that name. */
27	  blocked: string[]
28	  /** Specs marked implemented before their working files went. */
29	  implemented: string[]
30	  /** Working files deleted. */
31	  removed: string[]
