34	/**
35	 * Removes the working files of every feature that is finished, or whose spec
36	 * is gone, and that nobody has touched for a week. A finished feature's spec
37	 * is marked implemented first, so its stage outlives the files it was derived
38	 * from. A draft or a feature under development is never touched, however old.
39	 */
40	export async function sweepPlans(cwd: string, now: Date): Promise<SweepReport> {
41	  const report: SweepReport = { converted: [], moved: [], blocked: [], implemented: [], removed: [] }
42	  await moveLegacyFiles(cwd, report)
43	  const workDir = join(cwd, WORK_DIR)
44	  for (const name of (await namesIn(workDir)).filter((n) => n.endsWith(LEGACY_TASKS_SUFFIX))) {
45	    if (await convertLegacyBoard(join(workDir, name))) report.converted.push(`${WORK_DIR}/${name}`)
46	  }
47	  for (const [slug, files] of bySlug(await namesIn(workDir))) {
48	    const touched = await Promise.all(files.map(async (f) => (await stat(join(workDir, f))).mtimeMs))
49	    if (now.getTime() - Math.max(...touched) < WORKING_FILES_KEPT_MS) continue
50	    const spec = join(cwd, PLAN_DIR, `${slug}.spec.md`)
51	    const text = await readOptional(spec)
52	    if (text !== undefined && statusOf(text) !== 'implemented') {
53	      const tasks = await readTasks(join(workDir, `${slug}${TASKS_SUFFIX}`))
54	      // A postponed cleanup is the dev's word to come back to it, and the board holds what to come back to.
55	      if (!finished(statusOf(text), tasks) || (tasks.exists && tasks.cleanup === 'postponed')) continue
56	      await writeFile(spec, withStatus(text, 'implemented'), 'utf8')
57	      report.implemented.push(`${PLAN_DIR}/${slug}.spec.md`)
58	    }
59	    for (const file of files) {
60	      await rm(join(workDir, file))
61	      report.removed.push(`${WORK_DIR}/${file}`)
62	    }
63	    // A copy the move could not take, such as one an older branch brought back, goes with the feature it duplicates.
64	    for (const copy of report.blocked.filter((b) => WORKING_FILE.exec(b.slice(PLAN_DIR.length + 1))?.[1] === slug)) {
65	      await rm(join(cwd, copy))
66	      report.blocked.splice(report.blocked.indexOf(copy), 1)
67	      report.removed.push(copy)
68	    }
69	  }
70	  return report
71	}
