73	async function moveLegacyFiles(cwd: string, report: SweepReport): Promise<void> {
74	  const legacy = (await namesIn(join(cwd, PLAN_DIR))).filter((n) => WORKING_FILE.test(n))
75	  if (legacy.length === 0) return
76	  await mkdir(join(cwd, WORK_DIR), { recursive: true })
77	  for (const name of legacy) {
78	    const target = join(cwd, WORK_DIR, name)
79	    if (await exists(target)) {
80	      report.blocked.push(`${PLAN_DIR}/${name}`)
81	      continue
82	    }
83	    await rename(join(cwd, PLAN_DIR, name), target)
84	    report.moved.push(`${PLAN_DIR}/${name}`)
85	  }
86	}
