285	 * The board as the spec defines it: one task per scenario, named and grouped
286	 * by its title, delivering its live rules and edge cases, so every rule is
287	 * delivered by construction. Deriving again keeps each task's progress and
288	 * files; a scenario gone from the spec leaves its task marked removed. A task
289	 * a mapping run wrote before boards were derived keeps its rules once work on
290	 * it has started, and gives way while it is still open. `context` is where the
291	 * spec check found each scenario is built, by scenario title: the newest check
292	 * replaces a task's, and a scenario it left out keeps what the task had.
293	 */
294	export function deriveBoard(spec: Spec, board: TaskBoard = emptyBoard(), context: Map<string, string[]> = new Map()): TaskBoard {
295	  const found = new Map([...context].map(([title, paths]) => [title.trim().toLowerCase(), paths]))
296	  const scenarioTask = (t: Task) => sameName(t.group ?? '', t.name) || spec.scenarios.some((s) => sameName(s.title, t.name))
297	  const kept = board.tasks.filter((t) => !t.removed && !scenarioTask(t) && t.state !== 'open')
298	  const derived = new Map<string, { scenario: Scenario; delivers: string[] }>()
299	  for (const scenario of spec.scenarios) {
300	    const items = scenario.behaviours.flatMap((b) => [b, ...b.edges]).filter((i) => !i.removed)
301	    const delivers = items.map((i) => i.name).filter((name) => deliveredBy(kept, name) === undefined)
302	    if (delivers.length > 0) derived.set(scenario.title.trim().toLowerCase(), { scenario, delivers })
303	  }
304	  const tasks: Task[] = board.tasks.map((t) => {
305	    if (kept.includes(t)) return t
306	    const entry = derived.get(t.name.trim().toLowerCase())
307	    if (!entry) return t.removed ? t : { ...t, removed: true }
308	    derived.delete(t.name.trim().toLowerCase())
309	    return { ...t, ...fromScenario(entry.scenario, entry.delivers), context: found.get(t.name.trim().toLowerCase()) ?? t.context, removed: false }
