311	  for (const [key, { scenario, delivers }] of derived) {
312	    tasks.push({ ...fromScenario(scenario, delivers), files: [], newFiles: [], foreignFiles: [], context: found.get(key) ?? [], how: '', proves: [], note: '', built: '', state: 'open', removed: false })
